/**
 * Client for the FB_Exchange_Rates Named Credential.
 *
 * Calls GET callout:FB_Exchange_Rates/v1/latest?base=<base>&symbols=<csv>
 * and returns a map of the requested quote currency codes to their rates.
 */
public class ExchangeRateClient {

    private static final String NAMED_CREDENTIAL = 'FB_Exchange_Rates';
    private static final String RESOURCE_PATH = '/v1/latest';
    private static final Integer STATUS_OK = 200;
    private static final Integer STATUS_SERVICE_UNAVAILABLE = 503;
    private static final Integer CALLOUT_TIMEOUT_MS = 120000;

    /**
     * Thrown when the input is invalid, the callout fails, the service returns a
     * non-200 status, or the response cannot be parsed.
     */
    public class ExchangeRateException extends Exception {}

    /**
     * Retrieves live FX rates for the given base currency and set of quote currencies.
     *
     * @param baseCurrency   The base currency code (normalised to upper case).
     * @param quoteCurrencies The quote currency codes (normalised to upper case).
     * @return Map of every requested quote code to its rate.
     * @throws ExchangeRateException when validation, callout or parsing fails.
     */
    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        String base = normalise(baseCurrency);
        if (!isValidCode(base)) {
            throw new ExchangeRateException('Invalid base currency code: ' + baseCurrency);
        }

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currencies must not be null or empty.');
        }

        Set<String> quotes = new Set<String>();
        for (String quote : quoteCurrencies) {
            String normalised = normalise(quote);
            if (!isValidCode(normalised)) {
                throw new ExchangeRateException('Invalid quote currency code: ' + quote);
            }
            quotes.add(normalised);
        }

        // The set cannot be empty here (the input was non-empty and every entry added a code),
        // but guard defensively so we never call out with an empty symbols parameter.
        if (quotes.isEmpty()) {
            throw new ExchangeRateException('Quote currencies must not be null or empty.');
        }

        List<String> symbols = new List<String>(quotes);
        symbols.sort();
        String symbolsParam = String.join(symbols, ',');

        HttpResponse response = sendRequest(base, symbolsParam);

        // Retry once, with an identical request, if the service is temporarily unavailable.
        if (response.getStatusCode() == STATUS_SERVICE_UNAVAILABLE) {
            response = sendRequest(base, symbolsParam);
        }

        if (response.getStatusCode() != STATUS_OK) {
            throw new ExchangeRateException(
                'Exchange rate request failed with status code ' + response.getStatusCode()
            );
        }

        Map<String, Decimal> rates = new Map<String, Decimal>();
        try {
            Map<String, Object> body = asMap(JSON.deserializeUntyped(response.getBody()));
            Object ratesValue = body.get('rates');
            Map<String, Object> responseRates = asMap(ratesValue);
            if (responseRates == null) {
                throw new ExchangeRateException('Response body does not contain a rates object.');
            }

            for (String code : quotes) {
                Object rateValue = responseRates.get(code);
                if (rateValue == null) {
                    throw new ExchangeRateException('Response is missing a rate for currency ' + code);
                }
                rates.put(code, toDecimal(rateValue));
            }
        } catch (ExchangeRateException e) {
            throw e;
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse exchange rate response: ' + e.getMessage());
        }

        return rates;
    }

    /**
     * Builds and sends a single GET request through the Named Credential.
     */
    private static HttpResponse sendRequest(String base, String symbolsParam) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(
            'callout:' + NAMED_CREDENTIAL + RESOURCE_PATH +
            '?base=' + EncodingUtil.urlEncode(base, 'UTF-8') +
            '&symbols=' + EncodingUtil.urlEncode(symbolsParam, 'UTF-8')
        );
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');
        request.setTimeout(CALLOUT_TIMEOUT_MS);

        try {
            return new Http().send(request);
        } catch (System.CalloutException e) {
            throw new ExchangeRateException('Exchange rate callout failed: ' + e.getMessage());
        }
    }

    /**
     * Trims and upper-cases a currency code. Null is preserved so it can be reported as invalid.
     */
    private static String normalise(String code) {
        return code == null ? null : code.trim().toUpperCase();
    }

    /**
     * A valid currency code is exactly three letters A-Z after normalisation.
     */
    private static Boolean isValidCode(String code) {
        return code != null && Pattern.matches('^[A-Z]{3}$', code);
    }

    /**
     * Safely casts a deserialised JSON node to a String-keyed map, returning null otherwise.
     */
    private static Map<String, Object> asMap(Object value) {
        return value instanceof Map<String, Object> ? (Map<String, Object>) value : null;
    }

    /**
     * Converts a deserialised JSON number to a Decimal.
     */
    private static Decimal toDecimal(Object value) {
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer) {
            return Decimal.valueOf((Integer) value);
        }
        if (value instanceof Long) {
            return Decimal.valueOf((Long) value);
        }
        if (value instanceof Double) {
            return Decimal.valueOf((Double) value);
        }
        return Decimal.valueOf(String.valueOf(value));
    }
}
