/**
 * RecordSearchService
 *
 * Backs the admin "record finder" Lightning component. Power users supply an
 * object API name, the fields to select, a set of simple equality filters, an
 * optional order-by field and a row limit. Exactly one injection-safe SOQL
 * query is built and executed on behalf of the running user, honoring record
 * sharing and field-level security.
 *
 * Every invalid request is surfaced as RecordSearchService.SearchException.
 */
public with sharing class RecordSearchService {

    /** Thrown for every invalid request; no other exception type escapes. */
    public class SearchException extends Exception {}

    private static final Integer MIN_ROWS = 1;
    private static final Integer MAX_ROWS = 200;

    /**
     * Runs a single dynamic SOQL query for the requested object.
     *
     * @param objectApiName API name of the object to query (case-insensitive).
     * @param fields        API names of the fields to select (case-insensitive).
     * @param filters       Map of field API name -> value used as equality filters.
     * @param orderByField  Optional field API name to sort ascending by.
     * @param maxRows       Row limit, between 1 and 200 inclusive.
     * @return The matching records.
     */
    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // ----- Validate the row limit ---------------------------------------
        if (maxRows == null || maxRows < MIN_ROWS || maxRows > MAX_ROWS) {
            throw new SearchException(
                'maxRows must be a number between ' + MIN_ROWS + ' and ' + MAX_ROWS + '.'
            );
        }

        // ----- Resolve and validate the object ------------------------------
        if (String.isBlank(objectApiName)) {
            throw new SearchException('An object API name is required.');
        }

        Schema.SObjectType sObjType = resolveSObjectType(objectApiName);
        if (sObjType == null) {
            throw new SearchException('Unknown object: ' + objectApiName);
        }

        Schema.DescribeSObjectResult objDescribe = sObjType.getDescribe();
        if (!objDescribe.isAccessible()) {
            throw new SearchException(
                'You do not have read access to object ' + objDescribe.getName() + '.'
            );
        }

        // ----- Validate the requested fields --------------------------------
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }

        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();

        // SELECT Id plus every requested field, de-duplicated, in canonical casing.
        Set<String> selectFields = new LinkedHashSet<String>();
        selectFields.add('Id');
        for (String fieldName : fields) {
            Schema.SObjectField f = resolveField(fieldMap, fieldName);
            if (f == null) {
                throw new SearchException('Unknown field: ' + fieldName);
            }
            Schema.DescribeFieldResult fd = f.getDescribe();
            if (!fd.isAccessible()) {
                throw new SearchException(
                    'You do not have read access to field ' + fd.getName() + '.'
                );
            }
            selectFields.add(fd.getName());
        }

        // ----- Build the equality conditions --------------------------------
        List<String> conditions = new List<String>();
        if (filters != null && !filters.isEmpty()) {
            for (String filterField : filters.keySet()) {
                Schema.SObjectField f = resolveField(fieldMap, filterField);
                if (f == null) {
                    throw new SearchException('Unknown field: ' + filterField);
                }
                Schema.DescribeFieldResult fd = f.getDescribe();
                if (!fd.isAccessible()) {
                    throw new SearchException(
                        'You do not have read access to field ' + fd.getName() + '.'
                    );
                }
                if (!fd.isFilterable()) {
                    throw new SearchException(
                        'Field cannot be filtered: ' + fd.getName()
                    );
                }
                conditions.add(
                    fd.getName() + ' = ' + toSoqlLiteral(filters.get(filterField))
                );
            }
        }

        // ----- Assemble the query -------------------------------------------
        String soql = 'SELECT ' + String.join(new List<String>(selectFields), ', ')
                    + ' FROM ' + objDescribe.getName();

        if (!conditions.isEmpty()) {
            soql += ' WHERE ' + String.join(conditions, ' AND ');
        }

        if (String.isNotBlank(orderByField)) {
            Schema.SObjectField f = resolveField(fieldMap, orderByField);
            if (f == null) {
                throw new SearchException('Unknown field: ' + orderByField);
            }
            Schema.DescribeFieldResult fd = f.getDescribe();
            if (!fd.isAccessible()) {
                throw new SearchException(
                    'You do not have read access to field ' + fd.getName() + '.'
                );
            }
            if (!fd.isSortable()) {
                throw new SearchException(
                    'Field cannot be sorted: ' + fd.getName()
                );
            }
            soql += ' ORDER BY ' + fd.getName() + ' ASC';
        }

        soql += ' LIMIT ' + maxRows;

        // ----- Execute ------------------------------------------------------
        try {
            return Database.query(soql);
        } catch (Exception e) {
            throw new SearchException('Unable to run the search query: ' + e.getMessage());
        }
    }

    /** Case-insensitive lookup of an sObject type by API name. */
    private static Schema.SObjectType resolveSObjectType(String objectApiName) {
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();

        Schema.SObjectType result = globalDescribe.get(objectApiName);
        if (result != null) {
            return result;
        }

        result = globalDescribe.get(objectApiName.toLowerCase());
        if (result != null) {
            return result;
        }

        for (String key : globalDescribe.keySet()) {
            if (key.equalsIgnoreCase(objectApiName)) {
                return globalDescribe.get(key);
            }
        }
        return null;
    }

    /** Case-insensitive lookup of a field within an object's field map. */
    private static Schema.SObjectField resolveField(
        Map<String, Schema.SObjectField> fieldMap,
        String fieldName
    ) {
        if (String.isBlank(fieldName)) {
            return null;
        }

        Schema.SObjectField result = fieldMap.get(fieldName);
        if (result != null) {
            return result;
        }

        result = fieldMap.get(fieldName.toLowerCase());
        if (result != null) {
            return result;
        }

        for (String key : fieldMap.keySet()) {
            if (key.equalsIgnoreCase(fieldName)) {
                return fieldMap.get(key);
            }
        }
        return null;
    }

    /** Converts a filter value into a safe, properly typed SOQL literal. */
    private static String toSoqlLiteral(Object value) {
        if (value == null) {
            return 'null';
        }
        if (value instanceof Boolean) {
            return ((Boolean) value) ? 'true' : 'false';
        }
        if (value instanceof Date) {
            return ((Date) value).format('yyyy-MM-dd');
        }
        if (value instanceof Datetime) {
            return ((Datetime) value).formatGMT('yyyy-MM-dd\'T\'HH:mm:ss\'Z\'');
        }
        if (value instanceof Decimal) {
            return ((Decimal) value).toPlainString();
        }
        if (value instanceof Integer || value instanceof Long || value instanceof Double) {
            return String.valueOf(value);
        }
        // Strings, Ids and anything else are quoted and escaped against injection.
        return '\'' + String.escapeSingleQuotes(String.valueOf(value)) + '\'';
    }
