/**
 * Tests for AddressVerificationService.
 *
 * The callout is mocked with an inner HttpCalloutMock so no real HTTP traffic is made
 * and no org data is required (no SeeAllData).
 */
@isTest
private class AddressVerificationServiceTest {

    /**
     * HttpCalloutMock that records every request it receives and returns a configurable
     * status code / body.
     */
    public class AddressApiMock implements HttpCalloutMock {
        public Integer callCount = 0;
        public HttpRequest lastRequest;
        public Integer statusCode = 200;
        public String responseBody = '{"status":"VERIFIED","address":{}}';

        public HttpResponse respond(HttpRequest req) {
            callCount++;
            lastRequest = req;
            HttpResponse res = new HttpResponse();
            res.setStatusCode(statusCode);
            res.setBody(responseBody);
            res.setHeader('Content-Type', 'application/json');
            return res;
        }
    }

    private static AddressApiMock mockWith(Integer statusCode, String responseBody) {
        AddressApiMock mock = new AddressApiMock();
        mock.statusCode = statusCode;
        mock.responseBody = responseBody;
        Test.setMock(HttpCalloutMock.class, mock);
        return mock;
    }

    private static Account sampleAccount() {
        return new Account(
            BillingStreet = '123 Main St',
            BillingCity = 'Springfield',
            BillingPostalCode = '12345',
            BillingCountry = 'USA'
        );
    }

    // ------------------------------------------------------------------
    // Blank street -> SKIPPED, no callout
    // ------------------------------------------------------------------

    @isTest
    static void blankStreetSkipsCallout() {
        AddressApiMock mock = mockWith(
            200,
            '{"status":"CORRECTED","address":{"street":"x","city":"y","postalCode":"z","country":"w"}}'
        );

        Test.startTest();
        for (String blankStreet : new List<String>{ null, '', '   ' }) {
            Account acct = new Account(
                BillingStreet = blankStreet,
                BillingCity = 'Springfield',
                BillingPostalCode = '12345',
                BillingCountry = 'USA'
            );
            AddressVerificationService.Result result = AddressVerificationService.verify(acct);

            System.assertEquals('SKIPPED', result.status, 'A blank BillingStreet must produce SKIPPED');
            System.assertEquals(false, result.changed, 'SKIPPED must not report a change');
        }
        Test.stopTest();

        System.assertEquals(0, mock.callCount, 'No callout may be made when BillingStreet is blank');
        System.assertEquals(null, mock.lastRequest, 'No request should have been built for a blank street');
    }

    // ------------------------------------------------------------------
    // Request contract: POST, endpoint, header, JSON body
    // ------------------------------------------------------------------

    @isTest
    static void sendsCorrectRequestContract() {
        AddressApiMock mock = mockWith(200, '{"status":"VERIFIED","address":{}}');
        Account acct = sampleAccount();

        Test.startTest();
        AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals(1, mock.callCount, 'Exactly one callout must be made');
        HttpRequest req = mock.lastRequest;
        System.assertNotEquals(null, req, 'A request must have been sent');

        System.assertEquals('callout:FB_Address_API/v2/verify', req.getEndpoint(), 'Endpoint must match the contract');
        System.assertEquals('POST', req.getMethod(), 'Method must be POST');
        System.assertEquals('application/json', req.getHeader('Content-Type'), 'Content-Type header must be application/json');

        String rawBody = req.getBody();
        System.assertNotEquals(null, rawBody, 'Request must have a body');
        Map<String, Object> body = (Map<String, Object>) JSON.deserializeUntyped(rawBody);
        System.assertEquals(4, body.size(), 'Body must contain exactly the four address fields');
        System.assertEquals('123 Main St', body.get('street'), 'street must come from BillingStreet');
        System.assertEquals('Springfield', body.get('city'), 'city must come from BillingCity');
        System.assertEquals('12345', body.get('postalCode'), 'postalCode must come from BillingPostalCode');
        System.assertEquals('USA', body.get('country'), 'country must come from BillingCountry');
    }

    // ------------------------------------------------------------------
    // Non-200 -> exception whose message contains the status code
    // ------------------------------------------------------------------

    @isTest
    static void non200ThrowsWithStatusCodeInMessage() {
        for (Integer code : new List<Integer>{ 201, 302, 400, 404, 500 }) {
            AddressApiMock mock = mockWith(code, '{"status":"VERIFIED","address":{}}');
            Account acct = sampleAccount();

            Test.startTest();
            try {
                AddressVerificationService.verify(acct);
                System.assert(false, 'Expected AddressVerificationException for HTTP ' + code);
            } catch (AddressVerificationService.AddressVerificationException e) {
                System.assertNotEquals(null, e.getMessage(), 'Exception must carry a message');
                System.assert(
                    e.getMessage().contains(String.valueOf(code)),
                    'Exception message must contain the status code ' + code + ' but was: ' + e.getMessage()
                );
            }
            Test.stopTest();

            System.assertEquals(1, mock.callCount, 'The callout should still have been made');
        }
    }

    // ------------------------------------------------------------------
    // 200 VERIFIED -> untouched, changed false
    // ------------------------------------------------------------------

    @isTest
    static void verifiedLeavesAccountUntouched() {
        mockWith(
            200,
            '{"status":"VERIFIED","address":{"street":"999 Other St","city":"Othertown","postalCode":"00000","country":"Mexico"}}'
        );
        Account acct = sampleAccount();

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals('VERIFIED', result.status, 'Result status must echo the response status');
        System.assertEquals(false, result.changed, 'VERIFIED must not report a change');
        System.assertEquals('123 Main St', acct.BillingStreet, 'VERIFIED must not touch BillingStreet');
        System.assertEquals('Springfield', acct.BillingCity, 'VERIFIED must not touch BillingCity');
        System.assertEquals('12345', acct.BillingPostalCode, 'VERIFIED must not touch BillingPostalCode');
        System.assertEquals('USA', acct.BillingCountry, 'VERIFIED must not touch BillingCountry');
    }

    // ------------------------------------------------------------------
    // 200 INVALID -> untouched, changed false
    // ------------------------------------------------------------------

    @isTest
    static void invalidLeavesAccountUntouched() {
        mockWith(
            200,
            '{"status":"INVALID","address":{"street":"999 Other St","city":"Othertown","postalCode":"00000","country":"Mexico"}}'
        );
        Account acct = sampleAccount();

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals('INVALID', result.status, 'Result status must echo the response status');
        System.assertEquals(false, result.changed, 'INVALID must not report a change');
        System.assertEquals('123 Main St', acct.BillingStreet, 'INVALID must not touch BillingStreet');
        System.assertEquals('Springfield', acct.BillingCity, 'INVALID must not touch BillingCity');
        System.assertEquals('12345', acct.BillingPostalCode, 'INVALID must not touch BillingPostalCode');
        System.assertEquals('USA', acct.BillingCountry, 'INVALID must not touch BillingCountry');
    }

    // ------------------------------------------------------------------
    // 200 CORRECTED -> billing fields overwritten, changed true
    // ------------------------------------------------------------------

    @isTest
    static void correctedOverwritesBillingFields() {
        mockWith(
            200,
            '{"status":"CORRECTED","address":{"street":"1 New Rd","city":"Newtown","postalCode":"99999","country":"Canada"}}'
        );
        Account acct = sampleAccount();

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals('CORRECTED', result.status, 'Result status must echo the response status');
        System.assertEquals(true, result.changed, 'CORRECTED must report a change');
        System.assertEquals('1 New Rd', acct.BillingStreet, 'BillingStreet must be overwritten with the returned street');
        System.assertEquals('Newtown', acct.BillingCity, 'BillingCity must be overwritten with the returned city');
        System.assertEquals('99999', acct.BillingPostalCode, 'BillingPostalCode must be overwritten with the returned postalCode');
        System.assertEquals('Canada', acct.BillingCountry, 'BillingCountry must be overwritten with the returned country');
    }

    // ------------------------------------------------------------------
    // 200 CORRECTED -> every field is mapped from the correct response key
    // ------------------------------------------------------------------

    @isTest
    static void correctedMapsEachResponseFieldIndependently() {
        mockWith(
            200,
            '{"status":"CORRECTED","address":{"street":"S","city":"C","postalCode":"P","country":"K"}}'
        );
        Account acct = sampleAccount();

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals(true, result.changed);
        System.assertEquals('S', acct.BillingStreet, 'street must map to BillingStreet');
        System.assertEquals('C', acct.BillingCity, 'city must map to BillingCity');
        System.assertEquals('P', acct.BillingPostalCode, 'postalCode must map to BillingPostalCode');
        System.assertEquals('K', acct.BillingCountry, 'country must map to BillingCountry');
    }
}
