/**
 * PicklistService
 *
 * Admin utility that returns the active values of any picklist or
 * multi-select picklist field, resolved at runtime by object and field
 * API name. Both names are matched case-insensitively.
 */
public with sharing class PicklistService {

    /**
     * A single active picklist value.
     */
    public class Option {
        public String value;      // API value of the picklist entry
        public String label;      // UI label of the picklist entry
        public Boolean isDefault; // true only for the field's default value

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    /**
     * Thrown whenever the object/field cannot be resolved to a picklist field.
     */
    public class PicklistServiceException extends Exception {}

    /**
     * Returns the active values of the given picklist field, in the order in
     * which they are defined on the field. Inactive values are excluded.
     *
     * @param objectApiName API name of the SObject (standard or custom),
     *                      matched case-insensitively.
     * @param fieldApiName  API name of the picklist / multi-select picklist
     *                      field, matched case-insensitively.
     * @return List of active options in field definition order.
     * @throws PicklistServiceException if either name is null/blank, the object
     *         does not exist, the field does not exist on the object, or the
     *         field is not a picklist or multi-select picklist.
     */
    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException(
                'Both the object API name and the field API name are required.'
            );
        }

        String objectName = objectApiName.trim();
        String fieldName = fieldApiName.trim();

        try {
            Schema.SObjectType sObjectType = resolveSObjectType(objectName);
            if (sObjectType == null) {
                throw new PicklistServiceException(
                    'No SObject found with the API name \'' + objectName + '\'.'
                );
            }

            Map<String, Schema.SObjectField> fields =
                sObjectType.getDescribe().fields.getMap();

            Schema.SObjectField field = resolveField(fields, fieldName);
            if (field == null) {
                throw new PicklistServiceException(
                    'No field found with the API name \'' + fieldName +
                    '\' on SObject \'' + objectName + '\'.'
                );
            }

            Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
            Schema.DisplayType fieldType = fieldDescribe.getType();
            if (fieldType != Schema.DisplayType.PICKLIST &&
                fieldType != Schema.DisplayType.MULTIPICKLIST) {
                throw new PicklistServiceException(
                    'Field \'' + fieldName + '\' on SObject \'' + objectName +
                    '\' is not a picklist or multi-select picklist field.'
                );
            }

            List<Option> options = new List<Option>();
            for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
                if (entry.isActive()) {
                    options.add(
                        new Option(
                            entry.getValue(),
                            entry.getLabel(),
                            entry.isDefaultValue()
                        )
                    );
                }
            }
            return options;

        } catch (PicklistServiceException e) {
            throw e;
        } catch (Exception e) {
            // Never leak any other exception type out of this utility.
            throw new PicklistServiceException(
                'Unable to read picklist values for \'' + objectName + '.' + fieldName +
                '\': ' + e.getMessage()
            );
        }
    }

    // -------------------------------------------------------------------
    // Helpers
    // -------------------------------------------------------------------

    /**
     * Resolves an SObject type from its API name, case-insensitively.
     * Returns null when no matching SObject exists.
     */
    private static Schema.SObjectType resolveSObjectType(String objectName) {
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();

        Schema.SObjectType exactMatch = globalDescribe.get(objectName);
        if (exactMatch != null) {
            return exactMatch;
        }

        for (String apiName : globalDescribe.keySet()) {
            if (apiName.equalsIgnoreCase(objectName)) {
                return globalDescribe.get(apiName);
            }
        }
        return null;
    }

    /**
     * Resolves an SObjectField from a field map by API name,
     * case-insensitively. Returns null when no matching field exists.
     */
    private static Schema.SObjectField resolveField(
        Map<String, Schema.SObjectField> fields,
        String fieldName
    ) {
        Schema.SObjectField exactMatch = fields.get(fieldName);
        if (exactMatch != null) {
            return exactMatch;
        }

        for (String apiName : fields.keySet()) {
            if (apiName.equalsIgnoreCase(fieldName)) {
                return fields.get(apiName);
            }
        }
        return null;
    }
}
