/**
 * Transaction finalizer for ErpAccountSyncJob.
 *
 * Every run is logged in FB_Job_Log__c. Failed runs are retried, up to three
 * attempts in total; after the third failed attempt nothing further is enqueued.
 */
public class ErpSyncFinalizer implements Finalizer {

    private static final String JOB_NAME = 'ErpAccountSyncJob';
    private static final String STATUS_SUCCESS = 'Success';
    private static final String STATUS_FAILED = 'Failed';
    private static final Integer MAX_ATTEMPTS = 3;
    private static final Integer ERROR_FIELD_LENGTH = 255;

    private Set<Id> accountIds;
    private Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : new Set<Id>(accountIds);
        this.attempt = attempt == null ? 1 : attempt;
    }

    public void execute(FinalizerContext context) {
        Boolean failed = context.getResult() != ParentJobResult.SUCCESS;

        FB_Job_Log__c jobLog = new FB_Job_Log__c(
            Job_Name__c = JOB_NAME,
            Attempt__c = attempt,
            Status__c = failed ? STATUS_FAILED : STATUS_SUCCESS
        );

        if (failed) {
            jobLog.Error__c = truncate(getErrorMessage(context));
        }

        insert jobLog;

        // Retry only failed runs, and never beyond the third attempt.
        if (failed && attempt < MAX_ATTEMPTS) {
            System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
        }
    }

    private static String getErrorMessage(FinalizerContext context) {
        Exception cause = context.getException();
        return cause == null ? null : cause.getMessage();
    }

    private static String truncate(String value) {
        if (value == null) {
            return null;
        }
        return value.length() > ERROR_FIELD_LENGTH
            ? value.substring(0, ERROR_FIELD_LENGTH)
            : value;
    }
}
