```apex
/**
 * Maintains Account.FB_Open_Pipeline__c and Account.FB_Open_Opportunities__c
 * for every account touched by an Opportunity DML statement.
 *
 * Design notes:
 *  - Aggregates are always fully recomputed from the database for the affected
 *    accounts (never incremented/decremented), so the totals are correct even
 *    when several DML statements touch the same records inside one transaction
 *    (Flow + Apex, test methods, multiple updates in a loop, ...).
 *  - Only accounts whose stored values actually differ from the recomputed
 *    values are written back. This keeps the DML minimal and, importantly,
 *    breaks the re-entrancy cycle with the legacy AccountTrigger: that trigger
 *    updates open Opportunities on every Account update, which re-fires this
 *    handler, but by then the recomputed totals already match the stored
 *    values, so no further Account DML occurs and the chain terminates.
 *  - Bulk safe: one aggregate query and one Account query per invocation,
 *    regardless of how many Opportunities were passed in.
 *  - NULL Amounts contribute 0 to the pipeline (SUM ignores NULLs, we coerce
 *    the result to 0), and accounts with no open Opportunities are reset to
 *    0 / 0 rather than left blank.
 */
public inherited sharing class OpportunityPipelineHandler {

    public static void onAfterInsert(List<Opportunity> newOpportunities) {
        recalculate(collectAccountIds(newOpportunities));
    }

    public static void onAfterUpdate(List<Opportunity> newOpportunities, Map<Id, Opportunity> oldOpportunitiesById) {
        Set<Id> accountIds = collectAccountIds(newOpportunities);
        // An opportunity may have moved to another account, so both the old
        // and the new account need their totals recomputed.
        accountIds.addAll(collectAccountIds(oldOpportunitiesById.values()));
        recalculate(accountIds);
    }

    public static void onAfterDelete(List<Opportunity> oldOpportunities) {
        recalculate(collectAccountIds(oldOpportunities));
    }

    public static void onAfterUndelete(List<Opportunity> newOpportunities) {
        recalculate(collectAccountIds(newOpportunities));
    }

    private static Set<Id> collectAccountIds(List<Opportunity> opportunities) {
        Set<Id> accountIds = new Set<Id>();
        if (opportunities == null) {
            return accountIds;
        }
        for (Opportunity opportunity : opportunities) {
            if (opportunity != null && opportunity.AccountId != null) {
                accountIds.add(opportunity.AccountId);
            }
        }
        return accountIds;
    }

    private static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Map<Id, Decimal> openPipelineByAccountId = new Map<Id, Decimal>();
        Map<Id, Integer> openCountByAccountId = new Map<Id, Integer>();

        for (AggregateResult aggregate : [
            SELECT AccountId accountId,
                   SUM(Amount) openPipeline,
                   COUNT(Id) openCount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) aggregate.get('accountId');
            Decimal openPipeline = (Decimal) aggregate.get('openPipeline');
            openPipelineByAccountId.put(accountId, openPipeline == null ? 0 : openPipeline);
            openCountByAccountId.put(accountId, (Integer) aggregate.get('openCount'));
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account account : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Decimal openPipeline = openPipelineByAccountId.containsKey(account.Id)
                ? openPipelineByAccountId.get(account.Id)
                : 0;
            Integer openCount = openCountByAccountId.containsKey(account.Id)
                ? openCountByAccountId.get(account.Id)
                : 0;

            if (account.FB_Open_Pipeline__c != openPipeline
                    || account.FB_Open_Opportunities__c != openCount) {
                account.FB_Open_Pipeline__c = openPipeline;
                account.FB_Open_Opportunities__c = openCount;
                accountsToUpdate.add(account);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
