/**
 * OpportunityRollupService
 *
 * Rolls up closed-won Opportunity Amount by Account for the current calendar year.
 * Runs `with sharing`, so the running user's record-level sharing is respected.
 */
public with sharing class OpportunityRollupService {

    /**
     * Returns the sum of Amount for each account's won Opportunities whose CloseDate
     * falls in the current calendar year.
     *
     * @param accountIds Accounts to roll up. Null or empty returns an empty map.
     * @return A map keyed by every requested Account Id; accounts with no qualifying
     *         Opportunities (or only blank Amounts) map to 0, never null.
     */
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> wonByAccount = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return wonByAccount;
        }

        // Seed every requested account with 0 so accounts with no qualifying
        // Opportunities (or only blank Amounts) never come back as null, and so
        // no unrequested Id can ever appear as a key.
        for (Id accountId : accountIds) {
            wonByAccount.put(accountId, 0);
        }

        Integer currentYear = Date.today().year();
        Date startOfYear = Date.newInstance(currentYear, 1, 1);
        Date endOfYear = Date.newInstance(currentYear, 12, 31);

        // Single aggregate query: the database computes the sums, no Opportunity
        // records are loaded into memory. Aggregate queries in a `with sharing`
        // class honor the running user's sharing rules.
        List<AggregateResult> results = [
            SELECT AccountId, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsWon = true
              AND CloseDate >= :startOfYear
              AND CloseDate <= :endOfYear
            GROUP BY AccountId
        ];

        for (AggregateResult result : results) {
            Id accountId = (Id) result.get('AccountId');
            Decimal totalAmount = (Decimal) result.get('totalAmount');
            wonByAccount.put(accountId, totalAmount == null ? 0 : totalAmount);
        }

        return wonByAccount;
    }
}
