     * and OpportunityContactRoles (linked to the new Opportunities and
     * Contacts) using the relationship methods on fflib_ISObjectUnitOfWork.
     */
    public static final fflib_Application.UnitOfWorkFactory UnitOfWork =
        new fflib_Application.UnitOfWorkFactory(
            new List<Schema.SObjectType>{
                Account.SObjectType,
                Contact.SObjectType,
                Opportunity.SObjectType,
                OpportunityContactRole.SObjectType
            }
        );

    /**
     * Service factory. Implementation classes are resolved by convention:
     * IAccountsService -> AccountsServiceImpl.
     */
    public static final fflib_Application.ServiceFactory Service =
        new fflib_Application.ServiceFactory(
            new List<Type>{
                IAccountsService.class
            }
