public with sharing class CaseEscalationService {

    /**
     * Thrown when the service is asked to escalate without a valid reason.
     */
    public class EscalationException extends Exception {}

    /**
     * Escalates the supplied Cases by setting IsEscalated = true and Priority = 'High'
     * and creating one follow-up Task per escalated Case.
     *
     * @param caseIds Ids of the Cases to consider for escalation.
     * @param reason  Reason recorded on the created Tasks. Required (non-blank).
     */
    public static void escalate(Set<Id> caseIds, String reason) {
        if (String.isBlank(reason)) {
            throw new EscalationException('A reason must be provided to escalate a Case.');
        }

        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);

        List<Case> casesToEscalate = new List<Case>();
        List<Task> tasksToCreate = new List<Task>();
        Date tomorrow = Date.today().addDays(1);

        for (Case caseRecord : cases) {
            if (caseRecord.Status == 'Closed' || caseRecord.IsEscalated == true) {
                continue;
            }

            caseRecord.IsEscalated = true;
            caseRecord.Priority = 'High';
            casesToEscalate.add(caseRecord);

            tasksToCreate.add(new Task(
                Subject = 'Escalated: ' + reason,
                WhatId = caseRecord.Id,
                OwnerId = caseRecord.OwnerId,
                ActivityDate = tomorrow,
                Priority = 'High'
            ));
        }

        if (casesToEscalate.isEmpty()) {
            return;
        }

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        for (Case caseRecord : casesToEscalate) {
            uow.registerDirty(caseRecord);
        }

        for (Task taskRecord : tasksToCreate) {
            uow.registerNew(taskRecord);
        }

        uow.commitWork();
    }
}
