```apex
/**
 * Closes opportunities as won and notifies Fulfilment via the Deal_Won__e platform event.
 *
 * The opportunity updates and the platform events are registered with a single fflib unit of
 * work and committed once. The events are registered as "after transaction" publishes, so the
 * unit of work only publishes them once the opportunity DML has completed successfully; if the
 * save fails, nothing is published and the exception propagates to the caller.
 */
public with sharing class OpportunityWinService
{
    private static final String CLOSED_WON = 'Closed Won';

    /**
     * Marks the given opportunities as Closed Won (dated today) and publishes one Deal_Won__e
     * per opportunity that was actually closed.
     *
     * @param opportunityIds the opportunities to close (may be null or empty)
     * @return the number of opportunities closed
     */
    public static Integer markWon(Set<Id> opportunityIds)
    {
        if (opportunityIds == null || opportunityIds.isEmpty())
        {
            return 0;
        }

        List<Opportunity> opportunities =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        // Only touch opportunities that are not already Closed Won.
        List<Opportunity> opportunitiesToClose = new List<Opportunity>();
        for (Opportunity opportunity : opportunities)
        {
            if (opportunity.StageName != CLOSED_WON)
            {
                opportunitiesToClose.add(opportunity);
            }
        }

        if (opportunitiesToClose.isEmpty())
        {
            return 0;
        }

        Date closeDate = Date.today();

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        for (Opportunity opportunity : opportunitiesToClose)
        {
            opportunity.StageName = CLOSED_WON;
            opportunity.CloseDate = closeDate;
            uow.registerDirty(opportunity);

            // Queued for publication only after the unit of work has committed successfully.
            uow.registerPublishAfterTransaction(
                new Deal_Won__e(
                    Opportunity_Id__c = opportunity.Id,
                    Amount__c = opportunity.Amount
                )
            );
        }

        uow.commitWork();

        return opportunitiesToClose.size();
    }
}
