```apex
/**
 * Keeps Account.Rating in sync with the open pipeline.
 *
 * Recalculates the Account whenever an Opportunity is inserted, or its
 * StageName, Amount or AccountId (reparenting) changes.
 *
 * The recalculation is offloaded to an @future method so opportunity saves
 * stay fast. Because CPQ inserts/updates in batches of 200 and Apex allows
 * only 50 @future calls per transaction, we de-duplicate the AccountIds and
 * make a SINGLE bulk future call per trigger invocation.
 */
trigger OpportunityTrigger on Opportunity (after insert, after update) {

    Set<Id> accountIdsToRecalculate = new Set<Id>();

    if (Trigger.isInsert) {
        for (Opportunity opp : Trigger.new) {
            if (opp.AccountId != null) {
                accountIdsToRecalculate.add(opp.AccountId);
            }
        }
    }

    if (Trigger.isUpdate) {
        for (Opportunity opp : Trigger.new) {
            Opportunity oldOpp = Trigger.oldMap.get(opp.Id);

            Boolean stageChanged   = opp.StageName != oldOpp.StageName;
            Boolean amountChanged  = opp.Amount    != oldOpp.Amount;
            Boolean accountChanged = opp.AccountId != oldOpp.AccountId;

            if (stageChanged || amountChanged || accountChanged) {
                // New account (if any) is affected.
                if (opp.AccountId != null) {
                    accountIdsToRecalculate.add(opp.AccountId);
                }
                // Old account (if any) is affected when the opp was reparented.
                if (oldOpp.AccountId != null) {
                    accountIdsToRecalculate.add(oldOpp.AccountId);
                }
            }
        }
    }

    if (!accountIdsToRecalculate.isEmpty()) {
        AccountRatingService.recalculate(accountIdsToRecalculate);
    }
}
