```apex
/**
 * Matches imported Leads to existing Contacts by email address.
 *
 * Contract:
 *  - Returns a List<Id> with the same size and order as `leads`.
 *  - For each lead, the Id of the first Contact in `contacts` order whose email
 *    matches, or null when there is no match.
 *  - Email matching ignores case and leading/trailing whitespace.
 *  - A lead or contact with a blank email never matches.
 *  - Performs no SOQL/DML and does not modify any records.
 *
 * Implementation note: instead of a nested loop (leads x contacts, up to ~9M
 * comparisons in an import transaction), we index the contacts once in a Map
 * keyed by normalized email. This is O(n) and preserves the "first contact
 * wins" rule because we only insert a key the first time we see it.
 */
public with sharing class LeadContactMatcher {

    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> matchedContactIds = new List<Id>();

        if (leads == null || leads.isEmpty()) {
            return matchedContactIds;
        }

        // First pass: index contacts by normalized email, keeping the first
        // contact encountered for any duplicated email.
        Map<String, Id> contactIdByEmail = new Map<String, Id>();
        if (contacts != null) {
            for (Contact contact : contacts) {
                String key = normalizeEmail(contact.Email);
                if (key != null && !contactIdByEmail.containsKey(key)) {
                    contactIdByEmail.put(key, contact.Id);
                }
            }
        }

        // Second pass: one lookup per lead, preserving input order.
        for (Lead lead : leads) {
            String key = normalizeEmail(lead.Email);
            matchedContactIds.add(key == null ? null : contactIdByEmail.get(key));
        }

        return matchedContactIds;
    }

    /**
     * Normalizes an email for comparison. Returns null for a blank email so
     * that blank values can never collide with a real address.
     */
    private static String normalizeEmail(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase();
    }
}
